algorithms.pseudocode:
ENUMERATE-PROJECTIVE-CONE(q):
  seen ← empty set
  cone ← empty list
  for (a,b,c) in {0,...,q-1}^3:
    if (a,b,c) = (0,0,0): continue
    if (a²+b²-c²) mod q ≠ 0: continue
    rep ← NORMALIZE(a,b,c,q)
    if rep ∉ seen:
      seen ← seen ∪ {rep}
      cone ← cone ∪ [rep]
  return cone

NORMALIZE(v, q):
  for k in {0,1,2}:
    if v[k] mod q ≠ 0:
      return (v[0]/v[k], v[1]/v[k], v[2]/v[k]) mod q
  return nil
